{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 bucket encryption is not explicitly configured",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket stores sensitive CloudTrail audit logs but does not explicitly enforce server-side encryption in Terraform."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or deleted CloudTrail log objects cannot be recovered through S3 object history."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access protections are not configured",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket has no public access block, leaving it vulnerable to future public ACL or bucket-policy misconfiguration."
    },
    {
      "check_id": "UNKNOWN",
      "title": "S3 bucket does not enforce secure transport",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "No bucket policy denies requests made without TLS, so CloudTrail log objects could be accessed over insecure transport."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive deletion is enabled for the audit log bucket",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "Setting force_destroy to true permits Terraform to delete the bucket together with all retained CloudTrail logs, undermining audit-log retention."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = "smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}"
  force_destroy = false
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "cloudtrail_logs_tls" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    actions = ["s3:*"]
